/// C-FFI dispatch descriptor for SunSpec model 601. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_601: StaticModelSpec = StaticModelSpec {
    id: 601,
    length: model_601_c_length,
    writable: true,
    visit_read: model_601_c_visit_read,
    visit_write: model_601_c_visit_write,
};

fn model_601_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model601).model_length()
}

/// # Safety
/// For `kind` 1 or 2, `adapter` must point to a live `Model601{Stateful,Callback}Adapter`,
/// valid for the duration of the call.
unsafe fn model_601_c_visit_read(
    kind: u8,
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model601;
    let adapter: Option<&dyn ReadAdapter> = match kind {
        1 => Some(unsafe { &*(adapter as *const Model601StatefulAdapter) } as &dyn ReadAdapter),
        2 => Some(unsafe { &*(adapter as *const Model601CallbackAdapter) } as &dyn ReadAdapter),
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_601_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_601_c_visit_write(
    kind: u8,
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model601;
    let adapter: Option<&mut dyn WriteAdapter> = match kind {
        1 => {
            Some(unsafe { &mut *(adapter as *mut Model601StatefulAdapter) } as &mut dyn WriteAdapter)
        }
        2 => {
            Some(unsafe { &mut *(adapter as *mut Model601CallbackAdapter) } as &mut dyn WriteAdapter)
        }
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}
